public JsonObject toJson() {
        JsonObject json = ModRecipeSerializers.AMADRON_OFFERS.get().codec()
                .encode(this, JsonOps.INSTANCE, JsonOps.INSTANCE.mapBuilder())
                .build(new JsonObject())
                .resultOrPartial(s -> Log.error("can't create json: " + s))
                .orElseThrow()
                .getAsJsonObject();

        json.addProperty("offeringPlayerName", offeringPlayerName);
        json.addProperty("offeringPlayerId", offeringPlayerId.toString());
        json.addProperty("inStock", inStock);
        json.addProperty("pendingPayments", pendingPayments);
        if (providingPos != null) {
            json.add("providingPos", GlobalPosHelper.toJson(providingPos));
        }
        if (returningPos != null) {
            json.add("returningPos", GlobalPosHelper.toJson(returningPos));
        }
        return json;
    }

public static AmadronPlayerOffer fromJson(JsonObject json) {
        AmadronOffer baseOffer = ModRecipeSerializers.AMADRON_OFFERS.get().codec()
                .decode(JsonOps.INSTANCE, JsonOps.INSTANCE.getMap(json).getOrThrow())
                .resultOrPartial(err -> { throw new JsonSyntaxException(err); })
                .orElseThrow(() -> new JsonSyntaxException("invalid json syntax"));

        AmadronPlayerOffer playerOffer = new AmadronPlayerOffer(baseOffer.getOfferId(), baseOffer.getInput(), baseOffer.getOutput(),
                json.get("offeringPlayerName").getAsString(), UUID.fromString(json.get("offeringPlayerId").getAsString()),
                baseOffer.whitelist, baseOffer.blacklist);

        playerOffer.inStock = json.get("inStock").getAsInt();
        playerOffer.pendingPayments = json.get("pendingPayments").getAsInt();
        if (json.has("providingPos")) {
            playerOffer.providingPos = GlobalPosHelper.fromJson(json.get("providingPos").getAsJsonObject());
        }
        if (json.has("returningPos")) {
            playerOffer.returningPos = GlobalPosHelper.fromJson(json.get("returningPos").getAsJsonObject());
        }
        return playerOffer;
    }

@SubscribeEvent
    public void onAmadronSuccess(AmadronRetrievalEvent event) {
        AmadroneEntity drone = (AmadroneEntity) event.drone;

        AmadronOffer offer = AmadronOfferManager.getInstance().getOffer(drone.getHandlingOffer());

        AmadronPlayerOffer playerOffer = getPlayerOffer(offer);
        if (playerOffer == null) {
            // A normal (non-player) trade; just deliver the result
            doDelivery(drone, offer);
        } else {
            if (drone.getAmadronAction() == AmadronAction.TAKING_PAYMENT) {
                // Drone has just taken payment for player offer
                // Add a pending payment, and remove Amadron stock
                if (offer instanceof AmadronPlayerOffer) ((AmadronPlayerOffer) offer).addPayment(drone.getOfferTimes()); // don't use playerOffer here!
                playerOffer.onTrade(drone.getOfferTimes(), drone.getBuyingPlayer());
                doDelivery(drone, offer);
            } else if (drone.getAmadronAction() == AmadronAction.RESTOCKING) {
                // Drone is restocking Amadron - add stock
                playerOffer.setStock(playerOffer.getStock() + drone.getOfferTimes());
                NetworkHandler.sendNonLocal(new PacketAmadronStockUpdate(playerOffer.getOfferId(), playerOffer.getStock()));
                playerOffer.notifyRestock();
            }
            AmadronPlayerOffers.save();
        }
    }

@SubscribeEvent
    public void amadronHousekeeping(ServerTickEvent.Post event) {
        MinecraftServer server = ServerLifecycleHooks.getCurrentServer();

        if (reshuffleCounter++ >= ConfigHelper.common().amadron.reshuffleInterval.get() && !anyPlayerUsingAmadron(server)) {
            // don't reshuffle if any player has a tablet open, to avoid confusion
            AmadronOfferManager.getInstance().compileActiveOffersList();
            reshuffleCounter = 0;
        }
        if (server.getTickCount() % 600 == 0) {
            AmadronOfferManager.getInstance().tryRestockPlayerOffers();
        }
        Level overWorld = server.getLevel(Level.OVERWORLD);
        if (overWorld != null) {
            AmadronOfferManager.getInstance().checkForFullRebuild(overWorld);
        }
    }

public void tryRestockPlayerOffers() {
        boolean needSave = false;
        for (AmadronPlayerOffer offer : getPlayerOffers().values()) {
            AmadronPlayerOffer reversed = offer.getReversedOffer();
            BlockEntity provider = offer.getProvidingTileEntity();
            int possiblePickups = offer.getOutput().apply(
                    itemStack -> IOHelper.getInventoryForBlock(provider).map(h -> offer.getOutput().countTradesInInventory(h)).orElse(0),
                    fluidStack -> IOHelper.getFluidHandlerForBlock(provider).map(h -> offer.getOutput().countTradesInTank(h)).orElse(0)
            );
            if (possiblePickups > 0) {
                AmadroneEntity drone = AmadronMenu.retrieveOrder(null, offer.getReversedOffer(), possiblePickups,
                        offer.getProvidingPos(), offer.getProvidingPos());
                if (drone != null) {
                    drone.setHandlingOffer(reversed.getOfferId(), possiblePickups, ItemStack.EMPTY,
                            "Restock", AmadroneEntity.AmadronAction.RESTOCKING);
                }
            }
            if (offer.payout()) needSave = true;
        }
        if (needSave) saveAll();
    }

