public void recheckOpeners(Entity entity) {
		Level level = entity.level();
		List<Player> playersWithStorageOpen = getPlayersWithContainerOpen(level, entity.blockPosition());
		maxInteractionRange = 0.0;

		for (Player player : playersWithStorageOpen) {
			maxInteractionRange = Math.max(player.entityInteractionRange(), maxInteractionRange);
		}

		int numberOfPlayers = playersWithStorageOpen.size();
		if (openCount != numberOfPlayers) {
			if (numberOfPlayers != 0 && openCount == 0) {
				onOpen();
				level.gameEvent(null, GameEvent.CONTAINER_OPEN, entity.blockPosition());
			} else if (numberOfPlayers == 0) {
				onClose();
				level.gameEvent(null, GameEvent.CONTAINER_CLOSE, entity.blockPosition());
			}

			openCount = numberOfPlayers;
		}

		if (numberOfPlayers > 0) {
			nextOpenRecheck = level.getGameTime() + CHECK_TICK_DELAY;
		}
	}

public void tick(Level level, Entity entity) {
		if (level.getGameTime() > nextOpenRecheck && (level.getGameTime() - nextOpenRecheck < 3 * CHECK_TICK_DELAY || openCount > 0)) {
			recheckOpeners(entity);
		}
	}

public void incrementOpeners(Player player, Entity entity) {
		int i = openCount++;
		if (i == 0) {
			onOpen();
			player.level().gameEvent(player, GameEvent.CONTAINER_OPEN, entity.blockPosition());
			nextOpenRecheck = player.level().getGameTime() + CHECK_TICK_DELAY;
		}

		maxInteractionRange = Math.max(player.entityInteractionRange(), maxInteractionRange);
	}

public void decrementOpeners(Player player, Entity entity) {
		openCount--;
		if (openCount == 0) {
			onClose();
			player.level().gameEvent(player, GameEvent.CONTAINER_CLOSE, entity.blockPosition());
			maxInteractionRange = 0.0;
		}
	}

private List<Player> getPlayersWithContainerOpen(Level level, BlockPos pos) {
		double maxDistance = maxInteractionRange + 4.0;
		AABB aabb = new AABB(pos).inflate(maxDistance);
		return level.getEntities(EntityTypeTest.forClass(Player.class), aabb, this::isOwnContainer);
	}

private MovingStorageOpenersCounter getOpenersCounter() {
		if (openersCounter == null) {
			openersCounter = new MovingStorageOpenersCounter() {
				@Override
				protected void onOpen() {
					if (isBarrel()) {
						playSound(SoundEvents.BARREL_OPEN);
						updateBarrelOpenBlockState(true);
					} else if (isShulkerBox()) {
						playSound(SoundEvents.SHULKER_BOX_OPEN);
						if (getRenderBlockEntity() instanceof ShulkerBoxBlockEntity shulkerBoxBlockEntity) {
							shulkerBoxBlockEntity.setAnimationStatus(ShulkerBoxBlockEntity.AnimationStatus.OPENING);
						}
					} else if (isChest()) {
						if (isMainStorage) {
							playSound(SoundEvents.CHEST_OPEN);
						}
						if (getRenderBlockEntity() instanceof ChestBlockEntity chestBlockEntity) {
							chestBlockEntity.getChestLidController().shouldBeOpen(true);
						}
					}
				}

				@Override
				protected void onClose() {
					if (isBarrel()) {
						playSound(SoundEvents.BARREL_CLOSE);
						updateBarrelOpenBlockState(false);
					} else if (isShulkerBox()) {
						playSound(SoundEvents.SHULKER_BOX_CLOSE);
						if (getRenderBlockEntity() instanceof ShulkerBoxBlockEntity shulkerBoxBlockEntity) {
							shulkerBoxBlockEntity.setAnimationStatus(ShulkerBoxBlockEntity.AnimationStatus.CLOSING);
						}
					} else if (isChest()) {
						if (isMainStorage) {
							playSound(SoundEvents.CHEST_CLOSE);
						}
						if (getRenderBlockEntity() instanceof ChestBlockEntity chestBlockEntity) {
							chestBlockEntity.getChestLidController().shouldBeOpen(false);
						}
					}
				}

				@Override
				protected boolean isOwnContainer(Player player) {
					return StorageHolderBase.this.isOwnContainer(player);
				}
			};
		}
		return openersCounter;
	}

public void startOpen(Player player, Entity entity) {
		if (!(player.level() instanceof ServerLevel)) {
			return;
		}

		if (!player.isSpectator()) {
			getOpenersCounter().incrementOpeners(player, entity);
		}
		PiglinAi.angerNearbyPiglins(player, true);
		sendOpenness(entity);
	}

public void stopOpen(Player player, Entity entity) {
		if (!(player.level() instanceof ServerLevel)) {
			return;
		}

		if (!player.isSpectator()) {
			getOpenersCounter().decrementOpeners(player, entity);
		}
		sendOpenness(entity);
	}

public void tick(Entity entity) {
		Level level = getLevel();
		if (level == null) {
			return;
		}
		getOpenersCounter().tick(level, entity);
		if (level.isClientSide()) {
			clientTick(level);
			return;
		}
		if (isLinkedStorage()) {
			IStorageWrapper linkedHost = getStorageWrapper();
			if (linkedHost != NoopStorageWrapper.INSTANCE) {
				CompoundTag renderInfo = linkedHost.getRenderInfo().getNbt().copy();
				renderInfo.remove(RenderInfo.TANKS_TAG);
				renderInfo.remove(RenderInfo.BATTERY_TAG);
				CustomData previous = getSyncedStorageStack().get(ModCoreDataComponents.RENDER_INFO_TAG);
				if (previous == null || !previous.copyTag().equals(renderInfo)) {
					ItemStack projected = getSyncedStorageStack().copy();
					projected.set(ModCoreDataComponents.RENDER_INFO_TAG, CustomData.of(renderInfo.copy()));
					setSyncedStorageStack(projected);
					updateRenderAttributes = true;
				}
			}
		}
		if (isPacked() || isLinkedStorage() && !isPrimaryLinkedStorage()) {
			return;
		}
		if (isLinkedStorage() && level instanceof ServerLevel serverLevel && this instanceof ILinkedStorageBlockEndpoint endpoint) {
			StorageLinkedStorageJukeboxPlaybackAnchors.refreshEntityAnchor(serverLevel, entity, endpoint);
		}
		runTickableUpgrades(level);
		runPickupOnItemEntities(level);
	}
